<?php $editing=!empty($project);$title=$editing?'Edit Project':'New Project';require __DIR__.'/../layouts/header.php';$action=$editing?route('project.edit',['id'=>$project['id']]):route('projects');?><div class="pagehead"><h1><?=$title?></h1></div><form class="panel form" method="post" action="<?=$action?>"><?=csrf_field()?><div class="form-grid"><label>Client<select name="client_id" required><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=((int)($project['client_id']??0)===$c['id']?'selected':'')?>><?=e($c['full_name'])?></option><?php endforeach;?></select></label><label>Service<select name="service_id"><option value="">—</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=((int)($project['service_id']??0)===$s['id']?'selected':'')?>><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Project name<input name="name" required value="<?=e($project['name']??'')?>"></label><label>Status<select name="status"><?php foreach(['draft','upcoming','open','completed','closed','expired','cancelled','on_hold'] as $st):?><option value="<?=$st?>" <?=($project['status']??'draft')===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="start_date" required value="<?=e($project['start_date']??date('Y-m-d'))?>"></label><label>End date<input type="date" name="end_date" required value="<?=e($project['end_date']??date('Y-m-d',strtotime('+30 days')))?>"></label><label><input type="checkbox" name="is_recurring" value="1" <?=!empty($project['is_recurring'])?'checked':''?>> Recurring project</label><label>Recurring cycle days<input type="number" name="recurring_cycle_days" min="1" value="<?=e($project['recurring_cycle_days']??'30')?>"></label></div><button class="primary"><?=$editing?'Update Project':'Create Project'?></button></form><?php require __DIR__.'/../layouts/footer.php';?>
